const FN_80229030: usize = 0x8022_9030;

/// Intrusive-list insert: `(list, slot, node)`.
/// Ghidra: `80229160_FUN_80229160.c`.
const FN_80229160: usize = 0x8022_9160;

/// Intrusive-list remove: `(list, node)`.
/// Ghidra: `80229190_FUN_80229190.c`.
const FN_80229190: usize = 0x8022_9190;

/// Registers a `(previous, callback, argument)` record in the global callback
/// chain rooted at `r13-0x46A8`. Ghidra: `802dc780_FUN_802dc780.c`.
const FN_802DC780: usize = 0x802D_C780;

/// Texture-manager accessor (no arguments). Ghidra:
/// `80268c60_FUN_80268c60.c`. `// unknown:` manager identity.
const FN_80268C60: usize = 0x8026_8C60;

/// Texture-manager unlink helper: `(manager, object)`. Ghidra:
/// `80268d80_FUN_80268d80.c` (Ghidra also prints `thunk_FUN_80229190`).
const FN_80268D80: usize = 0x8026_8D80;

/// Pool pass 1 callback, called on `object+0xFC`-linked grids. Ghidra:
/// `80280870_FUN_80280870.c`.
const FN_80280870: usize = 0x8028_0870;

/// Pool pass 2 callback. Its Ghidra C contains `ldexpf`/`unaff_GQR0`, so it is
/// called as an opaque unit. Ghidra: `80280910_FUN_80280910.c`.
const FN_80280910: usize = 0x8028_0910;

/// Pool pass 3 callback. GQR-affected like [`FN_80280910`]. Ghidra:
/// `80280ba0_FUN_80280ba0.c`.
const FN_80280BA0: usize = 0x8028_0BA0;

/// Texture-grid per-cell apply pass. Walks one grid and updates the pool.
///
/// The grid layout comes from the `0x104`-byte object: row count at `+0x8C`,
/// column count at `+0x90`, row stride `0x10` and cell stride 4. For every
/// non-zero handle at `cell+0x0C` it builds two stack buffers through
/// `0x802821E0`, accumulates the `0x802631F0` status into a boolean, and then
/// picks the `0x80262840` mode from `object+0xBC` (`< 2` -> 0, else 1 plus a
/// `0x80263810` parameter-block call). Returns the accumulated boolean.
///
/// **Raw/Ghidra difference.** Ghidra prints the function with no parameter and
/// with a `uVar6` expression for the accumulator. The raw stream keeps the
/// object in `r3` across the `__savegprlr` helper, computes
/// `acc = ((acc | status) != 0)`, and returns it in `r3`.
///
/// # Original
/// - Ghidra: `FUN_80281D80` at `0x80281D80` (236 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80281d80_FUN_80281d80.c`
/// - Raw check: `work/dol/main.elf` at `0x80281D80..0x80281E6C`
///
/// # Arguments
/// * `object` - texture-grid object (`r3`); counts at `+0x8C/+0x90`, mode at
///   `+0xBC`.
///
/// # Returns
/// `1` when any per-cell status was non-zero, `0` otherwise.
///
/// # Side effects
/// Calls `0x802821E0`, `0x802631F0` and, per live cell, `0x80262840` plus an
/// optional `0x80263810`. No direct writes to `object`.
///
/// # Safety
/// `object` must be readable at the offsets above and every cell pointer must
/// be valid for at least `0x10` bytes. The two stack buffers must remain alive
/// across the calls (they are local arrays here).
///
/// # Confidence
/// high - the loop bounds, cell strides, buffers and boolean accumulation are
/// all visible in the raw stream; the callee roles are inferred from shape.
pub unsafe fn fn_80281d80(object: usize) -> i32 {
    let mut any = 0u32;
    let row_count = platform::read_u32(object + 0x8c);
    let mut row = 0u32;
    while row < row_count {
        let mut cell = object + row as usize * 0x10;
        let mut col = 0u32;
        while col < platform::read_u32(object + 0x90) {
            let texture = platform::read_u32(cell + 0x0c);
            if texture != 0 {
                // 56-byte status block and 16-byte parameter block, both passed
                // by pointer to the opaque GQR helper.
                let mut status = crate::platform::GuestLocal::new( [0u32; 14]);
                let mut params = crate::platform::GuestLocal::new( [0u32; 4]);
                call5(
                    FN_802821E0,
                    object as u32,
                    row,
                    col,
                    status.as_mut_ptr() as u32,
                    params.as_mut_ptr() as u32,
                );
                let result = call2(FN_802631F0, texture, status.as_mut_ptr() as u32);
                any = ((any | result) != 0) as u32;

                // observed 0x80281DE4: lwz r4,188(r25) = object+0xBC.
                if platform::read_u32(object + 0xbc) < 2 {
                    call2(FN_80262840, texture, 0);
                } else {
                    call2(FN_80262840, texture, 1);
                    call2(FN_80263810, texture, params.as_mut_ptr() as u32);
                }
            }
            cell += 4;
            col += 1;
        }
        row += 1;
    }
    any as i32
}

/// Releases every live texture handle of one grid.
///
/// The raw loop is transposed relative to [`fn_80281d80`]: the outer counter
/// walks the `+0x90` column count with a 4-byte stride and the inner counter
/// walks the `+0x8C` row count with a `0x10` stride. For every non-zero handle
/// at `cell+0x0C` it calls `0x802628A0(handle)`.
///
/// **Raw/Ghidra difference.** Ghidra prints `FUN_802628a0()` with no argument;
/// the raw stream loads the handle into `r3` at `0x80281EA0`.
///
/// # Original
/// - Ghidra: `FUN_80281E70` at `0x80281E70` (128 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80281e70_FUN_80281e70.c`
/// - Raw check: `work/dol/main.elf` at `0x80281E70..0x80281EEC`
///
/// # Arguments
/// * `object` - texture-grid object (`r3`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// One `0x802628A0` call per live cell; no direct writes to `object`.
///
/// # Safety
/// `object` must be readable and every cell must be valid for `0x10` bytes.
///
/// # Confidence
/// high - the raw loop and the handle argument are explicit.
pub unsafe fn fn_80281e70(object: usize) {
    let column_count = platform::read_u32(object + 0x90);
    let mut col = 0u32;
    while col < column_count {
        let mut cell = object + col as usize * 4;
        let mut row = 0u32;
        while row < platform::read_u32(object + 0x8c) {
            let texture = platform::read_u32(cell + 0x0c);
            if texture != 0 {
                call1(FN_802628A0, texture);
            }
            cell += 0x10;
            row += 1;
        }
        col += 1;
    }
}

/// Returns the lazily-built texture-pool singleton at `0x8041700C`.
///
/// On first use the function clears the pool word and the two list headers,
/// links both sentinel pairs to themselves (`0x80417014` and `0x80417020`),
/// registers the destructor `0x80282F70` through `0x802DC780`, and raises the
/// one-shot byte at `0x8042AD68` (`r13-0x4918`).
///
/// # Original
/// - Ghidra: `FUN_80282EF0` at `0x80282EF0` (124 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80282ef0_FUN_80282ef0.c`
/// - Raw check: `work/dol/main.elf` at `0x80282EF0..0x80282F6C`
///
/// # Arguments
/// None. The SDA addresses are absolute in `main.dol`: `r13 = 0x8042F680`.
///
/// # Returns
/// The singleton address `0x8041700C`.
///
/// # Side effects
/// On the first call, writes `0x8041700C..0x80417024`, the byte at
/// `0x8042AD68`, and the callback record at `0x80417000..0x80417008`.
///
/// # Safety
/// The absolute data addresses must be writable in the target image.
///
/// # Confidence
/// high - every absolute address and the self-links are explicit in the raw
/// stream. `// unknown:` the meaning of the second sentinel pair.
pub unsafe fn fn_80282ef0() -> usize {
    // r13 = 0x8042F680 (see docs/GLOSSARY.md); r13-0x4918 = 0x8042AD68.
    const SDA_8042AD68: usize = 0x8042_AD68;
    const POOL: usize = 0x8041_700C;

    if platform::read_u8(SDA_8042AD68) == 0 {
        platform::write_u8(POOL, 0);
        platform::write_u32(POOL + 0x04, 0);
        platform::write_u32(POOL + 0x08, (POOL + 0x08) as u32);
        platform::write_u32(POOL + 0x0c, (POOL + 0x08) as u32);
        platform::write_u32(POOL + 0x10, 0);
        platform::write_u32(POOL + 0x14, (POOL + 0x14) as u32);
        platform::write_u32(POOL + 0x18, (POOL + 0x14) as u32);
        call3(FN_802DC780, POOL as u32, 0x8028_2F70, 0x8041_7000);
        platform::write_u8(SDA_8042AD68, 1);
    }
    POOL
}

/// Pool-node destructor callback: unlinks the two child lists and optionally
/// frees the node.
///
/// # Original
/// - Ghidra: `FUN_80282F70` at `0x80282F70` (112 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80282f70_FUN_80282f70.c`
/// - Raw check: `work/dol/main.elf` at `0x80282F70..0x80282FE0`
///
/// # Arguments
/// * `node` - pool record (`r3`); child lists at `+0x04` and `+0x10`.
/// * `free_flag` - `r4`; the node is passed to `0x802B9280` only when `> 0`.
///
/// # Returns
/// `node`.
///
/// # Side effects
/// Up to two `0x80229030` unlink calls and an optional `0x802B9280` free.
///
/// # Safety
/// `node` must be null or writable for the two list nodes.
///
/// # Confidence
