pub unsafe fn fn_80282f70(node: usize, free_flag: i32) -> usize {
    if node != 0 {
        if node + 0x10 != 0 {
            call2(FN_80229030, (node + 0x10) as u32, 0);
        }
        if node + 0x04 != 0 {
            call2(FN_80229030, (node + 0x04) as u32, 0);
        }
        if free_flag > 0 {
            call1(FN_802B9280, node as u32);
        }
    }
    node
}

/// Initialises `size / 0x104` texture-grid objects and links them into the pool.
///
/// The pool byte at `+0x00` is the one-shot guard; when it is clear, the
/// function runs the loop `size / 0x104` times. Each object is constructed by
/// [`fn_80280660`] (when the base pointer is non-zero) and its `+0xFC` word is
