/// Builds a 3x4 rotation matrix from three angle bytes.
///
/// The three bytes at `object+0x9A`, `+0x9B` and `+0x9C` are added as
/// `byte * (pi/128)` to the object's base angles at `+0x40/+0x44/+0x48`, and
/// the owner's offsets at `+0x60/+0x64/+0x68` are added on top. A switch on
/// `axis` then builds the X, Y, Z or combined Euler matrix with the
/// sine/cosine pair returned by the GQR helper `0x802961E0`. The result is
/// twelve floats in row-major order; the homogeneous column is zero.
///
/// # Original
/// - Ghidra: `FUN_802A0A90` at `0x802A0A90` (868 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802a0a90_FUN_802a0a90.c`
/// - Raw check: `work/dol/main.elf` at `0x802A0A90..0x802A0DF4`
///
/// # Arguments
/// * `out` - 12-float (48-byte) matrix destination.
/// * `object` - angle/owner state object.
/// * `axis` - 0 = X, 1 = Y, 2 = Z, other = combined XYZ.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Up to three `0x802961E0` calls and twelve float stores at `out`.
///
/// # Safety
/// `object` and its owner must be readable; `out` writable for 48 bytes.
///
/// # Confidence
/// high - the angle scaling, the owner offsets and all four matrix arms are
/// raw-verified; the sincos callee itself is GQR/opaque.
pub unsafe fn fn_802a0a90(out: usize, object: usize, axis: i32) {
    // observed r2-0x40F4 = 0x3CC90FDB = 0.024543693 = 2*pi/256.
    let step = f32::from_bits(0x3CC9_0FDB);
    let mut x = read_f32(object + 0x40);
    let mut y = read_f32(object + 0x44);
    let mut z = read_f32(object + 0x48);

    let angle = platform::read_u8(object + 0x9a);
    if angle != 0 {
        x += angle as f32 * step;
    }
    let angle = platform::read_u8(object + 0x9b);
    if angle != 0 {
        y += angle as f32 * step;
    }
    let angle = platform::read_u8(object + 0x9c);
    if angle != 0 {
        z += angle as f32 * step;
    }

    let owner = platform::read_u32(object + 0xc8) as usize;
    x += read_f32(owner + 0x60);
    y += read_f32(owner + 0x64);
    z += read_f32(owner + 0x68);

    // observed stack layout: sin/cos pairs start at the identity values, so a
    // zero angle still produces an identity matrix row.
    let mut sin_x = crate::platform::GuestLocal::<f32>::new( 0.0f32);
    let mut cos_x = crate::platform::GuestLocal::<f32>::new( 1.0f32);
    let mut sin_y = crate::platform::GuestLocal::<f32>::new( 0.0f32);
    let mut cos_y = crate::platform::GuestLocal::<f32>::new( 1.0f32);
    let mut sin_z = crate::platform::GuestLocal::<f32>::new( 0.0f32);
    let mut cos_z = crate::platform::GuestLocal::<f32>::new( 1.0f32);

    if axis == 0 {
        if x != 0.0 {
            call_f64_2(
                FN_802961E0,
                -(x as f64),
                (sin_x.as_mut_ptr() as *mut f32) as u32,
                (cos_x.as_mut_ptr() as *mut f32) as u32,
            );
        }
        write_f32(out, 1.0);
        write_f32(out + 4, 0.0);
        write_f32(out + 8, 0.0);
        write_f32(out + 0x0c, 0.0);
        write_f32(out + 0x10, 0.0);
        write_f32(out + 0x14, *cos_x);
        write_f32(out + 0x18, -*sin_x);
        write_f32(out + 0x1c, 0.0);
        write_f32(out + 0x20, 0.0);
        write_f32(out + 0x24, *sin_x);
        write_f32(out + 0x28, *cos_x);
        write_f32(out + 0x2c, 0.0);
    } else if axis == 1 {
        if y != 0.0 {
            call_f64_2(
                FN_802961E0,
                -(y as f64),
                (sin_y.as_mut_ptr() as *mut f32) as u32,
                (cos_y.as_mut_ptr() as *mut f32) as u32,
            );
        }
        write_f32(out, *cos_y);
        write_f32(out + 4, 0.0);
        write_f32(out + 8, *sin_y);
        write_f32(out + 0x0c, 0.0);
        write_f32(out + 0x10, 0.0);
        write_f32(out + 0x14, 1.0);
        write_f32(out + 0x18, 0.0);
        write_f32(out + 0x1c, 0.0);
        write_f32(out + 0x20, -*sin_y);
        write_f32(out + 0x24, 0.0);
        write_f32(out + 0x28, *cos_y);
        write_f32(out + 0x2c, 0.0);
    } else if axis == 2 {
        if z != 0.0 {
            call_f64_2(
                FN_802961E0,
                -(z as f64),
                (sin_z.as_mut_ptr() as *mut f32) as u32,
                (cos_z.as_mut_ptr() as *mut f32) as u32,
            );
        }
        write_f32(out, *cos_z);
        write_f32(out + 4, -*sin_z);
        write_f32(out + 8, 0.0);
        write_f32(out + 0x0c, 0.0);
        write_f32(out + 0x10, *sin_z);
        write_f32(out + 0x14, *cos_z);
        write_f32(out + 0x18, 0.0);
        write_f32(out + 0x1c, 0.0);
        write_f32(out + 0x20, 0.0);
        write_f32(out + 0x24, 0.0);
        write_f32(out + 0x28, 1.0);
        write_f32(out + 0x2c, 0.0);
    } else {
        if x != 0.0 {
            call_f64_2(
                FN_802961E0,
                -(x as f64),
                (sin_x.as_mut_ptr() as *mut f32) as u32,
                (cos_x.as_mut_ptr() as *mut f32) as u32,
            );
        }
        if y != 0.0 {
            call_f64_2(
                FN_802961E0,
                -(y as f64),
                (sin_y.as_mut_ptr() as *mut f32) as u32,
                (cos_y.as_mut_ptr() as *mut f32) as u32,
            );
        }
        if z != 0.0 {
            call_f64_2(
                FN_802961E0,
                -(z as f64),
                (sin_z.as_mut_ptr() as *mut f32) as u32,
                (cos_z.as_mut_ptr() as *mut f32) as u32,
            );
        }
        write_f32(out, *cos_y * *cos_z);
        write_f32(out + 4, *sin_x * *sin_y * *cos_z - *cos_x * *sin_z);
        write_f32(
            out + 8,
            *cos_x * *sin_y * *cos_z + *sin_x * *sin_z,
        );
        write_f32(out + 0x0c, 0.0);
        write_f32(out + 0x10, *cos_y * *sin_z);
        write_f32(
            out + 0x14,
            *sin_x * *sin_y * *sin_z + *cos_x * *cos_z,
        );
        write_f32(
            out + 0x18,
            *cos_x * *sin_y * *sin_z - *sin_x * *cos_z,
        );
        write_f32(out + 0x1c, 0.0);
        write_f32(out + 0x20, -*sin_y);
        write_f32(out + 0x24, *cos_y * *sin_x);
        write_f32(out + 0x28, *cos_x * *cos_y);
        write_f32(out + 0x2c, 0.0);
    }
}

/// Returns the two orientation floats selected by byte `+0xBA`.
///
/// The byte is split as `remainder = byte % 3` and `quotient = byte / 3`.
/// The first value is `0`, `-value(+0x4C) * 0.5f`, or `-value(+0x4C)`; the
/// second is `0`, `value(+0x50) * 0.5f`, or `value(+0x50)`. The original
/// returns the two float bit patterns in `r3` and `r4`.
///
/// # Original
/// - Ghidra: `FUN_802AC340` at `0x802AC340` (200 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802ac340_FUN_802ac340.c`
/// - Raw check: `work/dol/main.elf` at `0x802AC340..0x802AC408`
///
/// # Arguments
/// * `object` - orientation state object.
///
/// # Returns
/// `(first, second)` as two `f32` values; the original returns them in `r3`
/// and `r4` as raw float words.
///
/// # Side effects
/// None; read-only.
///
/// # Safety
/// `object` must be readable at `+0x4C`, `+0x50` and `+0xBA`.
///
/// # Confidence
/// high - the divide-by-3 sequence and both halves are raw-verified.
pub unsafe fn fn_802ac340(object: usize) -> (f32, f32) {
    let mode = platform::read_u8(object + 0xba);
    let remainder = mode % 3;
    let quotient = mode / 3;

    let mut first = 0.0f32;
    if remainder == 1 {
        first = -read_f32(object + 0x4c) * 0.5;
    } else if remainder == 2 {
        first = -read_f32(object + 0x4c);
    }

    let second = if quotient == 1 {
        read_f32(object + 0x50) * 0.5
    } else if quotient == 2 {
        read_f32(object + 0x50)
    } else {
        0.0
    };

    (first, second)
}

/// Writes the four values of a half-angle orientation vector.
///
/// For the source pair `(+0x18, +0x1C)` the function stores
/// `[+value(+0x18) * 0.5, +value(+0x1C) * 0.5,
///   -value(+0x18) * 0.5, -value(+0x1C) * 0.5]` at `out[0..4]`. The raw
/// stream stores `[2]`, `[1]`, `[0]`, `[3]` in that order.
///
/// # Original
/// - Ghidra: `FUN_802AD520` at `0x802AD520` (56 bytes)
/// - Evidence: `work/ghidra/main-gb/export/802ad520_FUN_802ad520.c`
/// - Raw check: `work/dol/main.elf` at `0x802AD520..0x802AD558`
///
/// # Arguments
/// * `out` - four-float destination.
/// * `source` - orientation source.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Four `stfs` writes at `out`.
///
/// # Safety
/// `out` writable for 16 bytes; `source` readable at `+0x18/+0x1C`.
///
/// # Confidence
/// high - the negations, 0.5f constant and store order are raw-verified.
pub unsafe fn fn_802ad520(out: usize, source: usize) {
    let second = read_f32(source + 0x1c);
    let first = read_f32(source + 0x18);
    let scale = 0.5f32;

    write_f32(out + 8, first * scale);
    write_f32(out + 4, second * scale);
    write_f32(out, (-first) * scale);
    write_f32(out + 0x0c, (-second) * scale);
}

// ===========================================================================
// 8. Wave-9 extensions (`0x80280870..0x802AD920`)
// ===========================================================================
//
// This pass adds three related groups:
//
// 1. **Texture-list and material-name helpers** (`0x80284910..0x80295090`).
//    The five `0x80294D60..0x80295090` functions walk the same self-relative
//    name table: a 4-byte header offset, a `u16` count at `+0x04`, then
//    records of `u16 length + name bytes + 8-byte payload header`. The payload
//    header's first word is added to the table base to reach the entry.
// 2. **Draw-state list operations** (`0x80285C50..0x802957D0`). These are the
//    list primitives for the state records used by the wave-5 texture grid:
//    reset, count, drain to an array, unlink with a weight, and the
//    manager/slot release path.
// 3. **Texture command buffer** (`0x8028CD70..0x802970D0`). The sampler picks
//    an entry with a four-input hash, appends a `0x30`-byte command record to
//    the `0x400`-entry buffer, and later dispatches every record through
//    `0x80287C10` (GQR-affected; opaque) or a material virtual slot.
//
// None of the entries in this section contains `ldexpf(...)` or
// `unaff_GQR0`. `0x80287C10` itself is in the deferred `G` set and is only
// called by address.

// ---------------------------------------------------------------------------
// Wave-9 cross-lane callees.
// ---------------------------------------------------------------------------

/// `memset`-shaped helper: `(dst, value, length)`. Ghidra:
/// `800046b4_FUN_800046b4.c`. Translated in `runtime::crt` as `memset`.
const FN_800046B4: usize = 0x8000_46B4;

/// Small default callback stored in the effect/command delegate. Ghidra:
/// `800075d0_FUN_800075d0.c`. `// unknown:` exact role.
const FN_800075D0: usize = 0x8000_75D0;

/// Heap allocator used by the material constructors: `(heap, size)`.
/// Ghidra: `801d5540_FUN_801d5540.c`.
const FN_801D5540: usize = 0x801D_5540;

/// Intrusive-list link: `(header, node)`. Ghidra:
/// `80228df0_FUN_80228df0.c`.
const FN_80228DF0: usize = 0x8022_8DF0;

/// Intrusive-list unlink: `(header, node)`. Ghidra:
/// `80228f80_FUN_80228f80.c`.
const FN_80228F80: usize = 0x8022_8F80;

/// Intrusive-list iterator returning the next node after `previous`, or the
/// first node when `previous` is 0. Ghidra: `80228ff0_FUN_80228ff0.c`.
