// ---------------------------------------------------------------------------
// Shared command-buffer writer.
// ---------------------------------------------------------------------------

/// Appends one `0x30`-byte texture command record.
///
/// The buffer starts with a `u32` count followed by up to `0x400` records.
/// Each record is:
///
/// | Offset | Meaning |
/// |---|---|
/// | `+0x04` | record kind (`0` = direct, `1` = virtual dispatch) |
/// | `+0x05` | flag bits: `1` = colour0 present, `2` = colour1 present |
/// | `+0x06` | `u16` object id |
/// | `+0x08` | eight source bytes plus the source `u16` |
/// | `+0x14` | owner pointer; its `+0x10` reference count is incremented |
/// | `+0x18` | opaque argument word |
/// | `+0x1C` | optional first colour triple |
/// | `+0x28` | optional second colour triple |
///
/// # Arguments
/// * `entries` - buffer base (count at `+0`).
/// * `source` - ten-byte source command stream.
/// * `owner` - object whose `+0x10` reference count is raised.
/// * `arg4` - opaque word copied to `+0x18`.
/// * `id` - copied to `+0x06`.
/// * `color0`, `color1` - optional `[f32; 3]` pointers; 0 means absent.
/// * `kind` - byte stored at `+0x04`.
///
/// # Side effects
/// One record write plus one reference-count increment.
///
/// # Safety
/// `entries` must have room for one more record; `source` readable for ten
/// bytes; `owner` writable at `+0x10`. `entries` and `owner` must be distinct
/// (the original reloads the count between stores, which only differs if the
/// two objects alias).
///
/// # Confidence
/// high - the field order and the two optional colour blocks are raw-verified
/// in `0x80296DD0` and `0x80296F50`.
#[inline]
unsafe fn append_command_entry(
    entries: usize,
    source: usize,
    owner: usize,
    arg4: u32,
    id: u16,
    color0: usize,
    color1: usize,
    kind: u8,
) {
    let count = platform::read_u32(entries);
    if count >= 0x400 {
        return;
    }
    let entry = entries + count as usize * 0x30;

    platform::write_u8(entry + 0x04, kind);
    platform::write_u8(entry + 0x05, 0);
    platform::write_u16(entry + 0x06, id);
    platform::write_u16(entry + 0x08, platform::read_u16(source));
    let mut i = 0u32;
    while i < 8 {
        platform::write_u8(
            entry + 0x0a + i as usize,
            platform::read_u8(source + 2 + i as usize),
        );
        i += 1;
    }
    platform::write_u32(entry + 0x14, owner as u32);
    platform::write_u32(owner + 0x10, platform::read_u32(owner + 0x10).wrapping_add(1));
    platform::write_u32(entry + 0x18, arg4);

    if color0 != 0 {
        platform::write_u8(
            entry + 0x05,
            platform::read_u8(entry + 0x05) | 1,
        );
        write_f32(entry + 0x1c, read_f32(color0));
        write_f32(entry + 0x20, read_f32(color0 + 4));
        write_f32(entry + 0x24, read_f32(color0 + 8));
    }
    if color1 != 0 {
        platform::write_u8(
            entry + 0x05,
            platform::read_u8(entry + 0x05) | 2,
        );
        write_f32(entry + 0x28, read_f32(color1));
        write_f32(entry + 0x2c, read_f32(color1 + 4));
        write_f32(entry + 0x30, read_f32(color1 + 8));
    }

    platform::write_u32(entries, count.wrapping_add(1));
}

