    // 0x8042EB54 = 10.0f.
    let mut selected = 6.0f32;
    if value <= selected {
        selected = value;
        if value < -90.4 {
            selected = -90.4;
        }
    }
    let index = (10.0f32 * selected) as i32;
    // observed: the `+0x388` bias is added to the signed index before the
    // 4-byte scale, so `index == -0x388` selects the first real entry.
    let offset = (index as usize).wrapping_add(0x388).wrapping_mul(0x04);
