/// * `out0..out4` - five `u16` destinations (`r5..r9`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Five `u16` stores.
///
/// # Safety
/// Every `out` pointer must be writable for two bytes.
///
/// # Confidence
/// high - the clamp, the `*10` stride and the five field offsets are literal.
pub unsafe fn fn_802839d0(
    index: u32,
    out0: usize,
    out1: usize,
    out2: usize,
    out3: usize,
    out4: usize,
) {
    let selected = if (index as i32) < 0x80 {
        // observed: `param_1 & ~(param_1 >> 31)`, i.e. max(index, 0).
        index & !((index as i32 >> 31) as u32)
    } else {
        0x7f
    };

    let record = 0x802F_C700 + selected as usize * 0x0a;
    platform::write_u16(out0, platform::read_u16(record));
    platform::write_u16(out1, platform::read_u16(record + 0x02));
    platform::write_u16(out2, platform::read_u16(record + 0x04));
    platform::write_u16(out3, platform::read_u16(record + 0x06));
    platform::write_u16(out4, platform::read_u16(record + 0x08));
}

