/// Folds one four-float sample into a `[min_x, min_y, max_x, max_y]` quad.
///
/// The four independent compares reproduce `0x802AF4F0` exactly: slots 0/1
/// keep the minimum, slots 2/3 keep the maximum.
#[inline]
fn merge_bounds(bounds: &mut [f32; 4], sample: &[f32; 4]) {
    if sample[0] < bounds[0] {
        bounds[0] = sample[0];
    }
    if sample[1] < bounds[1] {
        bounds[1] = sample[1];
    }
    if sample[2] > bounds[2] {
        bounds[2] = sample[2];
    }
    if sample[3] > bounds[3] {
        bounds[3] = sample[3];
    }
}

