/// # Confidence
/// medium - the two lookup tables, the five index arms and the packing loop are
/// literal; the `0x43300000`/`2^52` and `2^52 + 2^31` pairs are the compiler's
/// unsigned and signed int-to-double idioms and the `0x802DCC4C` call is the
/// float-to-unsigned conversion they feed.
pub unsafe fn fn_8028dc70(desc: usize, out: usize, index: u32, frames: u32) {
    let key = platform::read_u8(desc + 0x03);
    let stride = platform::read_u8(0x8034_F3D8 + key as usize) as usize;
    let mask = platform::read_u8(0x8034_F4D8 + key as usize) as u32;
    if stride == 0 {
        return;
    }

    let frame = (track_frame_index(desc, index, frames) & 0xffff) as usize;
    let mut source = desc + 0x20 + stride * frame;
    let mut dest = out;
    let mut bit = 1u32;
    while bit <= mask {
        if key as u32 & bit != 0 {
            platform::write_u8(dest, platform::read_u8(source));
            source += 1;
        }
        dest += 1;
        bit = (bit & 0x7fff) << 1;
    }
}

/// Samples one word keyframe track into a packed channel row.
///
/// Identical to [`fn_8028dc70`] except that each stored channel is a whole
/// big-endian word: the frame base is `desc + 0x20 + stride*frame*4` and both
/// the source and the destination advance four bytes at a time.
///
/// # Original
/// - Ghidra: `FUN_8028DFC0` at `0x8028DFC0` (844 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8028dfc0_FUN_8028dfc0.c`
///
/// # Arguments
/// * `desc` - track descriptor (`r3`); same layout as [`fn_8028dc70`].
/// * `out` - destination word row (`r4`).
/// * `index` - requested frame (`r5`).
/// * `frames` - caller's frame count (`r6`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes one word per selected channel to `out`.
///
/// # Safety
/// `desc` must describe a readable keyframe array and `out` must have room for
/// at least the number of selected channels.
///
/// # Confidence
/// medium - the body is the byte sampler with a four-byte element; the two
/// lookup tables and all five index arms are shared through
/// [`track_frame_index`].
pub unsafe fn fn_8028dfc0(desc: usize, out: usize, index: u32, frames: u32) {
    let key = platform::read_u8(desc + 0x03);
    let stride = platform::read_u8(0x8034_F3D8 + key as usize) as usize;
    let mask = platform::read_u8(0x8034_F4D8 + key as usize) as u32;
    if stride == 0 {
        return;
    }

    let frame = (track_frame_index(desc, index, frames) & 0xffff) as usize;
    let mut source = desc + 0x20 + stride * frame * 4;
    let mut dest = out;
    let mut bit = 1u32;
    while bit <= mask {
        if key as u32 & bit != 0 {
            platform::write_u32(dest, platform::read_u32(source));
            source += 4;
        }
        dest += 4;
        bit = (bit & 0x7fff) << 1;
    }
}

