    if flags & 0x04 != 0 {
        extra[1] = read_f32(object + 0xd8);
    }
    if flags & 0x08 != 0 {
        extra[2] = read_f32(object + 0xdc);
    }
    if flags & 0x10 != 0 {
        extra[3] = read_f32(object + 0xe0);
    }

    // observed: `object+0xF8` is `3 * table index + flag pair`.
