/// Resolves one track descriptor to `(frame, group, exact)`.
///
/// This is the five-arm index resolver of the keyframe emitters, which differs
/// from [`track_frame_index`] in two places: the unreversed clamp and the
/// out-of-range tail use the key count itself rather than `count - 1`, and the
/// `0x40` ping-pong arm reports whether the caller landed exactly on a repeat
/// boundary.
///
/// # Arguments
/// * `record` - track descriptor: `+0x04` flags, `+0x05` step, `+0x08` count.
/// * `index` - requested frame.
/// * `frames` - the caller's frame count.
///
/// # Returns
/// `(frame, group, exact)`; `group` is the `index / (count-1)` quotient or the
/// step-derived repeat index, and `exact` is only ever set in the ping-pong
/// arm.
///
/// # Safety
/// `record` must be readable at `+0x04..+0x09`.
#[inline]
unsafe fn track_group_frame(record: usize, index: u32, frames: u32) -> (u32, u32, bool) {
    let count = platform::read_u16(record + 0x08) as u32;
    let flags = platform::read_u8(record + 0x04);
    let step = platform::read_u8(record + 0x05) as u32;
    let mut frame = 0u32;
    let mut group = 0u32;
    let mut exact = false;

    if flags & 0x20 == 0 && step < 2 {
        if flags & 0x80 == 0 {
            frame = if index < count { index & 0xffff } else { count };
        } else {
            frame = count.wrapping_mul(index) / frames & 0xffff;
        }
    } else if flags & 0x80 == 0 {
        frame = count;
        if count < 2 || flags & 0x40 == 0 {
            group = index / count;
            if flags & 0x20 == 0 && step <= group {
                group = step.wrapping_sub(1) & 0xff;
            } else {
                frame = index.wrapping_sub(group.wrapping_mul(count)) & 0xffff;
            }
        } else {
            frame = count - 1;
            group = index / frame;
            let mut resolved = false;
            if flags & 0x20 == 0 && step <= group {
                if step & 1 == 0 {
                    if group == step && index == group.wrapping_mul(frame) {
                        exact = true;
                    }
                    frame = 0;
                } else {
                    frame &= 0xffff;
                }
                group = step.wrapping_sub(1) & 0xff;
                resolved = true;
            }
            if !resolved {
                if group & 1 == 0 {
                    frame = index.wrapping_sub(group.wrapping_mul(frame)) & 0xffff;
                } else {
                    frame = frame
                        .wrapping_mul(group.wrapping_add(1))
                        .wrapping_sub(index)
                        & 0xffff;
                }
            }
        }
    } else if index < frames {
        frame = count;
        if count < 2 || flags & 0x40 == 0 {
            // observed: `(f32)step * ((f32)count / (f32)frames)` is rounded to
            // single precision before it is used as a `f64` multiplier.
            let scale = (step as f32 * (count as f32 / frames as f32)) as f64;
            let scaled = ((index as f32) as f64 * scale) as f32;
            let convert = crate::platform::guest_fn!(FN_802DCC4C, fn(f64) -> u32);
            group = convert((scaled / count as f32) as f64);
            frame = (scaled - (group.wrapping_mul(count)) as f32) as u32;
        } else {
            frame = count - 1;
            let biased = 1.0f32 + (frame as i32 as f32) * (step as f32);
            let scaled = index as f32 * (biased / frames as f32);
            let convert = crate::platform::guest_fn!(FN_802DCC4C, fn(f64) -> u32);
            let quantised = convert(scaled as f64);
            group = quantised / frame;
            if group < step {
                if group & 1 == 0 {
                    frame = quantised.wrapping_sub(group.wrapping_mul(frame)) & 0xffff;
                } else {
                    frame = frame
                        .wrapping_mul(group.wrapping_add(1))
                        .wrapping_sub(quantised)
                        & 0xffff;
                }
            } else {
                exact = step & 1 != 0;
                frame = if exact { frame & 0xffff } else { 0 };
                exact = !exact && index == frames - 1;
                group = step.wrapping_sub(1) & 0xff;
            }
        }
    } else if flags & 0x40 == 0 || step & 1 != 0 {
        frame = count;
        group = step.wrapping_sub(1) & 0xff;
    } else {
        frame = 0;
        group = step.wrapping_sub(1) & 0xff;
    }

    (frame, group, exact)
}

/// Finds the first key entry whose time is at least `value`.
///
/// This is the forward half of the binary search in [`fn_8028cee0`]: the entry
/// tables are `0x0C`-byte records whose first halfword is the key time, so the
/// index arithmetic is `entry * 0x0C`. The returned index is the low bound of
/// the final interval, i.e. where the caller starts its forward walk.
///
/// # Safety
/// `keys` must describe `count` readable `0x0C`-byte entries.
#[inline]
unsafe fn key_forward_start(keys: usize, count: u32, value: u32) -> i32 {
    let mut high = count as i32 - 1;
    let mut middle = high / 2;
    let mut low = 0i32;
    let first = platform::read_u16(keys) as u32;
    if value < first || value == first {
        return 0;
    }
    if value <= platform::read_u16(keys + high as usize * 0x0c) as u32 {
        let mut sample = platform::read_u16(keys + middle as usize * 0x0c) as u32;
        loop {
            let mut next_low = low;
            if low >= middle {
                break;
            }
            let mut next_high = middle;
            if value != sample {
                next_low = middle;
                next_high = high;
                if value <= sample {
                    next_low = low;
                    next_high = middle;
                }
            }
            middle = (next_low + next_high) / 2;
            sample = platform::read_u16(keys + middle as usize * 0x0c) as u32;
            low = next_low;
            high = next_high;
        }
        return low;
    }
    high
}

/// Finds the last key entry whose time is at most `value`.
///
/// The reverse counterpart of [`key_forward_start`]: the caller walks the
/// entries downwards from the returned index.
///
/// # Safety
/// `keys` must describe `count` readable `0x0C`-byte entries.
#[inline]
unsafe fn key_reverse_start(keys: usize, count: u32, value: u32) -> i32 {
    let mut high = count as i32 - 1;
    let mut middle = high / 2;
    let mut low = 0i32;
    if value < platform::read_u16(keys) as u32 {
        return 0;
    }
    low = high;
    let last = platform::read_u16(keys + high as usize * 0x0c) as u32;
    if value <= last && value != last {
        let mut sample = platform::read_u16(keys + middle as usize * 0x0c) as u32;
        low = 0;
        while low < middle {
            let mut next_low = middle;
            if value != sample && value <= sample {
                next_low = low;
                high = middle;
            }
            middle = (next_low + high) / 2;
            sample = platform::read_u16(keys + middle as usize * 0x0c) as u32;
            low = next_low;
        }
    }
    low
}

/// Emits every key entry of one track that lies between two frames.
///
/// The descriptor uses the simple `0x0C`-byte entry layout: the key count is
/// the halfword at `+0x20`, the entries start at `+0x24`, and each entry's
/// first halfword is its key time. The function resolves the requested frame
/// twice - once for `index` and once for `index + 1` - and then walks the
/// entries either forwards, backwards, over whole repeat groups or in ping-pong
/// order, calling [`FN_8028CD70`] for every entry in range.
///
/// # Original
/// - Ghidra: `FUN_8028CEE0` at `0x8028CEE0` (3,468 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8028cee0_FUN_8028cee0.c`
///
/// # Arguments
/// * `record` - track descriptor (`r3`); flags at `+0x04`, step at `+0x05`,
///   count at `+0x08`, key array at `+0x24`.
/// * `out` - destination pointer forwarded to [`FN_8028CD70`] (`r4`).
/// * `index` - requested frame (`r5`).
/// * `context` - opaque word forwarded unchanged (`r6`).
/// * `frames` - the caller's frame count (`r7`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// One [`FN_8028CD70`] call per emitted entry, i.e. one or more writes to the
/// caller's destination per key in range.
///
/// # Safety
/// `record` must describe a readable key array and `out` must be writable for
/// every emitted entry.
///
/// # Confidence
/// medium - both resolvers, all four walk arms and every bound are literal; the
/// two pointer sums at `+0x10`/`+0x14` and the `context` word are forwarded
/// opaquely because the callee is outside this lane.
pub unsafe fn fn_8028cee0(record: usize, out: usize, index: u32, context: u32, frames: u32) {
    let flags = platform::read_u8(record + 0x04);
    let key_count = platform::read_u16(record + 0x20) as u32;
    let key_table = record + 0x24;

    // observed: two pointer sums built from the signed `+0x0C`, `+0x10` and
    // `+0x14` fields; both are only forwarded to the callee.
    let inner_a = (record as i32)
        .wrapping_add(0x20)
        .wrapping_add(platform::read_i32(record + 0x10))
        .wrapping_add(platform::read_i32(record + 0x0c)) as usize;
    let inner_b = (inner_a as i32).wrapping_add(platform::read_i32(record + 0x14)) as usize;

    let (start_frame, start_group, exact) = track_group_frame(record, index, frames);
    let (mut end_frame, end_group, _) = track_group_frame(record, index.wrapping_add(1), frames);

    let emit = |entry: usize| unsafe {
        call7(
            FN_8028CD70,
            entry as u32,
            context,
            record as u32,
            inner_a as u32,
            inner_b as u32,
            out as u32,
            start_group,
        );
    };

    if start_group == end_group {
        let target = start_frame & 0xffff;
        if target == (end_frame & 0xffff) {
            if !exact {
                return;
            }
            end_frame = 1;
        }
        let limit = end_frame & 0xffff;
        if target < limit {
            let mut walker = key_forward_start(key_table, key_count, target);
            let mut entry = key_table + walker as usize * 0x0c;
            while walker < key_count as i32 {
                let time = platform::read_u16(entry) as u32;
                if target <= time {
                    if limit <= time {
                        break;
                    }
                    emit(entry);
                }
                entry += 0x0c;
                walker += 1;
            }
        } else {
            let mut walker = key_reverse_start(key_table, key_count, target);
            let mut entry = key_table + walker as usize * 0x0c;
            while walker >= 0 {
                let time = platform::read_u16(entry) as u32;
                if time <= target {
                    if time <= limit {
                        break;
                    }
                    emit(entry);
                }
                entry -= 0x0c;
                walker -= 1;
            }
        }
    } else if flags & 0x40 == 0 {
        let target = start_frame & 0xffff;
        let limit = end_frame & 0xffff;
        let start = key_forward_start(key_table, key_count, target);
        let mut entry = key_table + start as usize * 0x0c;
        let mut walker = start;
        while walker < key_count as i32 {
            if target <= platform::read_u16(entry) as u32 {
                emit(entry);
            }
            entry += 0x0c;
            walker += 1;
        }

        let mut group = start_group;
        loop {
            group = group.wrapping_add(1);
            if group >= end_group {
                break;
            }
            let mut inner = key_table;
            let mut step = 0i32;
            while step < key_count as i32 {
                emit(inner);
                inner += 0x0c;
                step += 1;
            }
        }

        let mut entry = key_table;
        let mut walker = 0i32;
        while walker < key_count as i32 && (platform::read_u16(entry) as u32) < limit {
            emit(entry);
            entry += 0x0c;
            walker += 1;
        }
    } else {
        let target = start_frame & 0xffff;
        let limit = end_frame & 0xffff;
        if start_group & 1 == 0 {
            let start = key_forward_start(key_table, key_count, target);
            let mut entry = key_table + start as usize * 0x0c;
            let mut walker = start;
            while walker < key_count as i32 {
                let time = platform::read_u16(entry) as u32;
                if target <= time {
                    if time == key_count - 1 {
                        break;
                    }
                    emit(entry);
                }
                entry += 0x0c;
                walker += 1;
            }
        } else {
            let start = key_reverse_start(key_table, key_count, target);
            let mut entry = key_table + start as usize * 0x0c;
            let mut walker = start;
            while walker >= 0 {
                let time = platform::read_u16(entry) as u32;
                if time <= target {
                    if time == 0 {
                        break;
                    }
                    emit(entry);
                }
                entry -= 0x0c;
                walker -= 1;
            }
        }

        let mut group = start_group;
        loop {
            group = group.wrapping_add(1);
            if group >= end_group {
                break;
            }
            if start_group & 1 == 0 {
                let mut entry = key_table;
                let mut walker = 0i32;
                while walker < key_count as i32
                    && platform::read_u16(entry) as u32 != key_count - 1
                {
                    emit(entry);
                    entry += 0x0c;
                    walker += 1;
                }
            } else {
                let mut walker = key_count as i32 - 1;
                let mut entry = key_table + walker as usize * 0x0c;
                while walker >= 0 && platform::read_u16(entry) != 0 {
                    emit(entry);
                    entry -= 0x0c;
                    walker -= 1;
                }
            }
        }

        if end_group & 1 == 0 {
            let mut walker = 0i32;
            let mut entry = key_table;
            while walker < key_count as i32 && (platform::read_u16(entry) as u32) < limit {
                emit(entry);
                entry += 0x0c;
                walker += 1;
            }
        } else {
            let mut walker = key_count as i32 - 1;
            let mut entry = key_table + walker as usize * 0x0c;
            while walker >= 0 && limit < platform::read_u16(entry) as u32 {
                emit(entry);
                entry -= 0x0c;
                walker -= 1;
            }
        }
    }
}

/// Emits `count` zero vertex components into the GX FIFO at the element size of
/// a GX component type.
///
/// `0`/`1` (`GX_U8`/`GX_S8`) store one byte, `2`/`3` (`GX_U16`/`GX_S16`) one
/// halfword and `4` (`GX_F32`) one float zero; types 5..7 have no store in the
/// original and are ignored. Used by [`fn_8029bab0`], whose strip vertices are
/// entirely zero.
///
/// # Safety
/// Every store targets the write-gather FIFO, which only exists on Wii
/// hardware; `count` is at most four in the caller.
unsafe fn gx_emit_zero_components(count: u32, comp_type: u32) {
    let mut i = 0;
    while i < count {
        match comp_type {
            0 | 1 => platform::write_u8(GX_FIFO, 0),
            2 | 3 => platform::write_u16(GX_FIFO, 0),
            // observed: the float arm stores sdata2 0x8042EF1C, which holds
            // +0.0 (a zero bit pattern), so this is not a rounded value.
            4 => write_f32(GX_FIFO, 0.0),
            _ => {}
        }
        i += 1;
    }
}

/// Pushes one material's TEV/texgen state, then flushes the vertex pipeline
/// with a degenerate eight-vertex triangle strip whose attributes are all zero.
///
/// The material id byte at `material+0x97` is compared with the copy cached in
/// the render object at `+0xB0`. On a miss (or when `force` is non-zero) the id
/// is stored into `+0xB0` and `+0xB4` and one packed GX register word is emitted
/// through `0x801C86C0` from `mask+2`, the id, `mask+4`, `mask+3` and
/// `material+0x98`. The TEV colour-channel sync `0x8029C080` and the per-channel
/// texgen builder `0x8029C820` then run; if either reported work, the texgen
/// builder reported nothing (`r3 == 0`), bit 3 of `*mask` is clear and a flag
/// four pointer hops away from `material+0xC8` is set, the function reads the
/// five vertex-attribute descriptors (POS, NRM, CLR0, CLR1, TEX0) from the GX
/// state cache, issues `GXBegin(0x98, GX_VTXFMT0, 8)` and writes eight
/// all-zero vertices formatted exactly as the current VAT describes them.
///
/// # Original
/// - Ghidra: `FUN_8029bab0` at `0x8029BAB0` (1484 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8029bab0_FUN_8029bab0.c`
/// - Raw check: `work/dol/main.elf` at `0x8029BAB0..0x8029C07C`
///
/// # Arguments
/// - `object`: render state object that caches the material id at
///   `+0xB0`/`+0xB4` (the same object [`fn_8029c080`] mutates through
///   `+0xB8..+0xCF`).
/// - `material`: material descriptor; id byte `+0x97`, sub-id `+0x98`, owner
///   pointer `+0xC8`.
/// - `mask`: attribute flag word; bit 3 suppresses the strip and bytes `+2..+4`
///   feed the register write.
/// - `scene`: forwarded to the texgen builder as its fourth argument.
/// - `force`: non-zero bypasses the id-cache compare and forces both channel
///   emitters.
/// - `redraw`: non-zero marks the channel state dirty without an id change.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Two `u32` stores on `object`, one `0x801C86C0` register word, the two
/// channel emitters, `GXBegin(0x98,0,8)` and up to 8 × 16 FIFO element writes
/// (position, normal, two colours, tex coord). Nothing is drawn when the guards
/// fail.
///
/// # Safety
/// `object` and `material` must be live and writable at the offsets above;
/// `mask` must be readable for five bytes; the chain
/// `material+0xC8 -> +0x20 -> +0xBC -> +0x20` must be dereferenceable when bit
/// 3 of `*mask` is clear; the GX FIFO and state cache must be initialised.
///
/// # Confidence
/// medium - every guard, call shape and emitted store is raw-verified, and the
/// Ghidra export's collapsed `_DAT_cc008000` masks were resolved to the real
/// `stb`/`sth`/`stfs` runs in `main.elf`; the per-attribute component counts are
/// `// inferred:` from GX's compCnt encoding (POS 2/3, NRM 3, colour 3/4, TEX
/// 1/2) rather than from a symbol.
pub unsafe fn fn_8029bab0(
    object: usize,
    material: usize,
    mask: usize,
    scene: u32,
    force: u32,
    redraw: i32,
) {
    let material_id = platform::read_u8(material + 0x97) as u32;
    let mut changed = false;
    if force == 0 && platform::read_u32(object + 0xb0) == material_id {
        // observed: cache hit - neither the id nor the register word is
        // written.
    } else {
        platform::write_u32(object + 0xb0, material_id);
        platform::write_u32(object + 0xb4, material_id);
        call5(
            FN_801C86C0,
            platform::read_u8(mask + 2) as u32,
            material_id,
            platform::read_u8(mask + 4) as u32,
            platform::read_u8(mask + 3) as u32,
            platform::read_u8(material + 0x98) as u32,
        );
        changed = true;
    }

    // observed: both channel emitters are declared void in this module, yet the
    // original tests `r3` after each call, so they run by address through
    // `callN` and the register is captured instead of being discarded.
    let channels_dirty = redraw != 0 || changed;
    let colour_changed = call4(
        FN_8029C080,
        object as u32,
        material as u32,
        mask as u32,
        force,
    ) != 0;
    let texgen = call5(
        FN_8029C820,
        object as u32,
        material as u32,
        mask as u32,
        scene,
        force,
    );
    let draw = (channels_dirty || colour_changed) && texgen == 0;

    if platform::read_u16(mask) & 8 != 0 {
        return;
    }
    // observed: five dereferences - owner, owner+0x20, +0xBC, +0x20, then the
    // byte at +0xC064.
    let owner = platform::read_u32(material + 0xc8) as usize;
    let scene_root = platform::read_u32(owner + 0x20) as usize;
    let manager = platform::read_u32(scene_root + 0xbc) as usize;
    let render_root = platform::read_u32(manager + 0x20) as usize;
    if platform::read_u8(render_root + 0xc064) == 0 || !draw {
        return;
    }

    // observed: five attribute probes in this order. The attribute ids are the
    // GX ones: 9 = POS, 10 = NRM, 11 = CLR0, 12 = CLR1, 13 = TEX0.
    let mut pos_desc = crate::platform::GuestLocal::<u32>::new( 0u32);
    let mut nrm_desc = crate::platform::GuestLocal::<u32>::new( 0u32);
    let mut clr0_desc = crate::platform::GuestLocal::<u32>::new( 0u32);
    let mut clr1_desc = crate::platform::GuestLocal::<u32>::new( 0u32);
    let mut tex0_desc = crate::platform::GuestLocal::<u32>::new( 0u32);
    call2(FN_801C3E20, 9, (pos_desc.as_mut_ptr() as *mut u32) as u32);
    call2(FN_801C3E20, 10, (nrm_desc.as_mut_ptr() as *mut u32) as u32);
    call2(FN_801C3E20, 0xb, (clr0_desc.as_mut_ptr() as *mut u32) as u32);
    call2(FN_801C3E20, 0xc, (clr1_desc.as_mut_ptr() as *mut u32) as u32);
    call2(FN_801C3E20, 0xd, (tex0_desc.as_mut_ptr() as *mut u32) as u32);

    let mut pos_low = crate::platform::GuestLocal::<u32>::new( 0u32);
    let mut pos_type = crate::platform::GuestLocal::<u32>::new( 0u32);
    let mut nrm_low = crate::platform::GuestLocal::<u32>::new( 0u32);
    let mut nrm_type = crate::platform::GuestLocal::<u32>::new( 0u32);
    let mut clr0_low = crate::platform::GuestLocal::<u32>::new( 0u32);
    let mut clr1_low = crate::platform::GuestLocal::<u32>::new( 0u32);
    let mut tex0_low = crate::platform::GuestLocal::<u32>::new( 0u32);
    let mut tex0_type = crate::platform::GuestLocal::<u32>::new( 0u32);
    // The colour probes' second output is never read, and every call shares one
    // third output slot in the original frame.
    let mut colour_unused = crate::platform::GuestLocal::<u32>::new( 0u32);
    let mut count = crate::platform::GuestLocal::<u32>::new( 0u32);
    call5(
        FN_801C44A0,
        0,
        9,
        (pos_low.as_mut_ptr() as *mut u32) as u32,
        (pos_type.as_mut_ptr() as *mut u32) as u32,
        (count.as_mut_ptr() as *mut u32) as u32,
    );
    call5(
        FN_801C44A0,
        0,
        10,
        (nrm_low.as_mut_ptr() as *mut u32) as u32,
        (nrm_type.as_mut_ptr() as *mut u32) as u32,
        (count.as_mut_ptr() as *mut u32) as u32,
    );
    call5(
        FN_801C44A0,
        0,
        0xb,
        (clr0_low.as_mut_ptr() as *mut u32) as u32,
        (colour_unused.as_mut_ptr() as *mut u32) as u32,
        (count.as_mut_ptr() as *mut u32) as u32,
    );
    call5(
        FN_801C44A0,
        0,
        0xc,
        (clr1_low.as_mut_ptr() as *mut u32) as u32,
        (colour_unused.as_mut_ptr() as *mut u32) as u32,
        (count.as_mut_ptr() as *mut u32) as u32,
    );
    call5(
        FN_801C44A0,
        0,
        0xd,
        (tex0_low.as_mut_ptr() as *mut u32) as u32,
        (tex0_type.as_mut_ptr() as *mut u32) as u32,
        (count.as_mut_ptr() as *mut u32) as u32,
    );

    // observed: GXBegin(GX_TRIANGLESTRIP = 0x98, GX_VTXFMT0, 8).
    call3(FN_801C5570, 0x98, 0, 8);

    let mut vertex = 8;
    while vertex != 0 {
        // 9 = POS. `pos_low` is the low bit of the component count: 1 -> XYZ,
        // 0 -> XY. Descriptor 2/3 emit a single index instead of direct data.
        if *pos_desc == 1 {
            if *pos_low == 1 {
                gx_emit_zero_components(3, *pos_type);
            } else if *pos_low == 0 {
                gx_emit_zero_components(2, *pos_type);
            }
        } else if *pos_desc == 2 {
            platform::write_u8(GX_FIFO, 0);
        } else if *pos_desc == 3 {
            platform::write_u16(GX_FIFO, 0);
        }

        // 10 = NRM. Always three components, but only for the signed 8/16-bit
        // and float types; the unsigned types fall through with no store.
        if *nrm_desc == 1 {
            if *nrm_low == 0 && (*nrm_type == 1 || *nrm_type == 3 || *nrm_type == 4) {
                gx_emit_zero_components(3, *nrm_type);
            }
        } else if *nrm_desc == 2 {
            platform::write_u8(GX_FIFO, 0);
        } else if *nrm_desc == 3 {
            platform::write_u16(GX_FIFO, 0);
        }

        // 11 = CLR0 and 12 = CLR1. The low bit is the RGB/RGBA select, so the
        // run is three or four bytes; the element type is always a byte.
        if *clr0_desc == 1 {
            gx_emit_zero_components(3 + *clr0_low, 0);
        } else if *clr0_desc == 2 {
            platform::write_u8(GX_FIFO, 0);
        } else if *clr0_desc == 3 {
            platform::write_u16(GX_FIFO, 0);
        }

        if *clr1_desc == 1 {
            gx_emit_zero_components(3 + *clr1_low, 0);
        } else if *clr1_desc == 2 {
            platform::write_u8(GX_FIFO, 0);
        } else if *clr1_desc == 3 {
            platform::write_u16(GX_FIFO, 0);
        }

        // 13 = TEX0. `tex0_low` is the count minus one: 1 -> ST, 0 -> S.
        if *tex0_desc == 1 {
            if *tex0_low == 1 {
                gx_emit_zero_components(2, *tex0_type);
            } else if *tex0_low == 0 {
                gx_emit_zero_components(1, *tex0_type);
            }
        } else if *tex0_desc == 2 {
            platform::write_u8(GX_FIFO, 0);
        } else if *tex0_desc == 3 {
            platform::write_u16(GX_FIFO, 0);
        }

        vertex -= 1;
    }
}

/// Applies one particle emitter's six optional transform terms to a three-float
/// vector, in place.
///
/// The emitter record switches each term on with its own non-zero scalar, and the
/// body evaluates them in this order:
///
/// 1. `+0x68` **replaces** the vector with `position * scale`; when the scale is
///    zero the vector is zeroed instead (the original branches rather than
///    multiplying).
/// 2. `+0x6C` adds `axis * scale`.
/// 3. `+0x70` adds a small random rotation: three LCG draws are turned into the
///    angles `2*pi*r`, the three `0x802961E0` table samplers return their
///    sine/cosine pairs, and the two blended terms are combined exactly as the
///    original does (`cos3*cos1*sin2 + sin1*sin3` and
///    `sin3*cos1*sin2 - sin1*cos3`, plus `cos2*cos1` on z).
/// 4. `+0x74` adds `ring * scale`.
/// 5. `+0x7C` adds a rotation of the unit Y axis: with `+0x80 == 0` the fixed
///    angles `+0x84/+0x88/+0x8C` build the matrix; otherwise a random spin
///    (`+0x80*r2`, `2*pi*r1`, `0`) is composed with the fixed-angle matrix first.
///    The matrix's second column (`m11`, `m21`, `m31`) is added.
/// 6. a non-zero signed byte at `+0x66` scales the whole vector by
///    `1 - 0.01*byte*(2*r - 1)` from one more LCG draw.
///
/// Every `psq_l`/`psq_st` in this entry uses `I = 0`, i.e. GQR0. The image sets
/// all eight GQRs to `0` (float) in the init path at `0x801AB150`, and the only
/// other writer, `0x802EA6FC`, is a save-area restore, so the paired-single
/// quantisation ladders the export prints collapse to plain `f32` moves. That is
/// why this body is fully reconstructible while the `GQR3` samplers it calls are
/// not.
///
/// # Original
/// - Ghidra: `FUN_80296820` at `0x80296820` (1216 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80296820_FUN_80296820.c`
/// - Raw check: `work/dol/main.elf` at `0x80296820..0x80296CE0`
///
/// # Arguments
/// - `ctx`: `r3`; the original never reads it.
/// - `out`: `r4`; three writable floats, updated in place.
/// - `emitter`: `r5`; emitter record, scalars at `+0x66..+0x8C`, LCG state at
///   `+0xEC`.
/// - `param_4`: `r6`; the caller's "middle" vector, never read here.
/// - `ring`: `r7`; three floats added through the `+0x74` term.
/// - `position`: `r8`; three floats scaled by the `+0x68` term.
/// - `axis`: `r9`; three floats scaled by the `+0x6C` term.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Between three and nine `f32` stores to `out`, one LCG state store at
/// `emitter+0xEC` per active random term, three `0x802961E0` samplers, one or two
/// `0x802963B0` matrix builds, and one `0x801C1160` or `0x801C0540` transform.
///
/// # Safety
/// `out`, `ring`, `position`, `axis` and the 12-float stack matrices must be
/// writable, `emitter` readable through `+0xEC`, and the four callees must exist
/// with the shapes used below.
///
/// # Confidence
/// medium - every guard, offset, store and call was read from `main.elf`; the
/// term order and the `cos/sin` combination are literal. `0x802961E0` and
/// `0x802963B0` are GQR3-dependent and stay opaque, called by address with the
/// exact register shape this entry uses.
pub unsafe fn fn_80296820(
    ctx: u32,
    out: usize,
    emitter: usize,
    param_4: usize,
    ring: usize,
    position: usize,
    axis: usize,
) {
    let _ = (ctx, param_4);

    // observed: sdata2 under r2 = 0x80433080 - 0x8042ED30 = 0.0,
    // 0x8042ED34 = 65536.0, 0x8042ED38 = 2.0, 0x8042ED3C = pi,
    // 0x8042ED40 = 1.0, 0x8042ED44 = 0.01.
    let zero = 0.0f32;
    let one = 1.0f32;
    let two = 2.0f32;
    let hundredth = 0.01f32;
    let divisor = 65536.0f32;
    let pi = core::f32::consts::PI;
    let step = |seed: u32| {
        seed.wrapping_mul(0x0003_43fd)
            .wrapping_add(0x0026_9ec3)
    };

    // 1. Replace (or zero) the vector with the scaled position.
    let scale = read_f32(emitter + 0x68);
    if scale == zero {
        write_f32(out, zero);
        write_f32(out + 4, zero);
        write_f32(out + 8, zero);
    } else {
        write_f32(out, read_f32(position) * scale);
        write_f32(out + 4, read_f32(position + 4) * scale);
        write_f32(out + 8, read_f32(position + 8) * scale);
    }

    // 2. Add the scaled axis.
    let drift = read_f32(emitter + 0x6c);
    if drift != zero {
        write_f32(out, read_f32(out) + read_f32(axis) * drift);
        write_f32(out + 4, read_f32(out + 4) + read_f32(axis + 4) * drift);
        write_f32(out + 8, read_f32(out + 8) + read_f32(axis + 8) * drift);
    }

    // 3. Add the random spin. Three draws are consumed and only the last seed is
    // written back, exactly like the original's single `stw`.
    let strength = read_f32(emitter + 0x70);
    if strength != zero {
        let seed1 = step(platform::read_u32(emitter + 0xec));
        let seed2 = step(seed1);
        let seed3 = step(seed2);
        platform::write_u32(emitter + 0xec, seed3);
        let r1 = (seed1 >> 16) as f32 / divisor;
        let r2 = (seed2 >> 16) as f32 / divisor;
        let r3 = (seed3 >> 16) as f32 / divisor;

        // `0x802961E0` writes its signed value through `r3` and its cosine term
        // through `r4`; both are single `f32` stores (W = 1).
        let trig = crate::platform::guest_fn!(FN_802961E0, fn(f64, *mut f32, *mut f32));
        let mut sin1 = zero;
        let mut cos1 = zero;
        trig((two * (pi * r1)) as f64, &mut sin1, &mut cos1);
        let mut sin2 = zero;
        let mut cos2 = zero;
        trig((two * (pi * r2)) as f64, &mut sin2, &mut cos2);
        let mut sin3 = zero;
        let mut cos3 = zero;
        trig((two * (pi * r3)) as f64, &mut sin3, &mut cos3);

        let cross = cos1 * sin2;
        write_f32(
            out,
            read_f32(out) + strength * (cos3 * cross + sin1 * sin3),
        );
        write_f32(
            out + 4,
            read_f32(out + 4) + strength * (sin3 * cross - sin1 * cos3),
        );
        write_f32(out + 8, read_f32(out + 8) + cos2 * (strength * cos1));
    }

    // 4. Add the scaled ring vector.
    let velocity = read_f32(emitter + 0x74);
    if velocity != zero {
        write_f32(out, read_f32(out) + read_f32(ring) * velocity);
        write_f32(out + 4, read_f32(out + 4) + read_f32(ring + 4) * velocity);
        write_f32(out + 8, read_f32(out + 8) + read_f32(ring + 8) * velocity);
    }

    // 5. Add the scaled rotation of the unit Y axis.
    let magnitude = read_f32(emitter + 0x7c);
    if magnitude != zero {
        let mut warp = crate::platform::GuestLocal::new( [zero; 3]);
        if read_f32(emitter + 0x80) == zero {
            let mut matrix = crate::platform::GuestLocal::new( [0u32; 12]);
            call_f32x3_1(
                FN_802963B0,
                read_f32(emitter + 0x84),
                read_f32(emitter + 0x88),
                read_f32(emitter + 0x8c),
                matrix.as_mut_ptr() as u32,
            );
            warp[0] = zero;
            warp[1] = one;
            warp[2] = zero;
            call3(
                FN_801C1160,
                matrix.as_ptr() as u32,
                warp.as_ptr() as u32,
                warp.as_mut_ptr() as u32,
            );
        } else {
            let seed1 = step(platform::read_u32(emitter + 0xec));
            let seed2 = step(seed1);
            platform::write_u32(emitter + 0xec, seed2);
            let r1 = (seed1 >> 16) as f32 / divisor;
            let r2 = (seed2 >> 16) as f32 / divisor;

            // `// inferred:` the first matrix is the random spin, the second the
            // fixed euler triple; `0x801C0540` composes them into the spin slot.
            let mut spin = crate::platform::GuestLocal::new( [0u32; 12]);
            call_f32x3_1(
                FN_802963B0,
                read_f32(emitter + 0x80) * r2,
                two * (pi * r1),
                zero,
                spin.as_mut_ptr() as u32,
            );
            let mut fixed = crate::platform::GuestLocal::new( [0u32; 12]);
            call_f32x3_1(
                FN_802963B0,
                read_f32(emitter + 0x84),
                read_f32(emitter + 0x88),
                read_f32(emitter + 0x8c),
                fixed.as_mut_ptr() as u32,
            );
            call3(
                FN_801C0540,
                fixed.as_ptr() as u32,
                spin.as_ptr() as u32,
                spin.as_mut_ptr() as u32,
            );
            // observed: the transformed unit Y axis is column 1 of the 3x4
            // row-major result, i.e. words 1, 5 and 9.
            warp[0] = f32::from_bits(spin[1]);
            warp[1] = f32::from_bits(spin[5]);
            warp[2] = f32::from_bits(spin[9]);
        }
        write_f32(out, read_f32(out) + magnitude * warp[0]);
        write_f32(out + 4, read_f32(out + 4) + magnitude * warp[1]);
        write_f32(out + 8, read_f32(out + 8) + magnitude * warp[2]);
    }

    // 6. Scale the whole vector by a random percentage.
    let percent = platform::read_u8(emitter + 0x66) as i8;
    if percent != 0 {
        let seed = step(platform::read_u32(emitter + 0xec));
        platform::write_u32(emitter + 0xec, seed);
        let fraction = (seed >> 16) as f32 / divisor;
        let factor = one - hundredth * (percent as f32) * (two * fraction - one);
        write_f32(out, read_f32(out) * factor);
        write_f32(out + 4, read_f32(out + 4) * factor);
        write_f32(out + 8, read_f32(out + 8) * factor);
    }
}

/// Shape sampler `0x8028E890` (selector `0`), translated as [`fn_8028e890`];
/// the dispatcher still calls it by address.
/// Ghidra: `8028e890_FUN_8028e890.c`.
const FN_8028E890: usize = 0x8028_E890;

/// Shape sampler `0x8028ED30` (selector `1`), translated as [`fn_8028ed30`].
/// Ghidra: `8028ed30_FUN_8028ed30.c`.
const FN_8028ED30: usize = 0x8028_ED30;

/// Shape sampler `0x8028F2D0` (selector `2`), translated as [`fn_8028f2d0`].
/// Ghidra: `8028f2d0_FUN_8028f2d0.c`.
const FN_8028F2D0: usize = 0x8028_F2D0;

/// Shape sampler `0x80290690` (selector `3`), translated as [`fn_80290690`];
/// the dispatcher still calls it by address. Ghidra:
/// `80290690_FUN_80290690.c`.
const FN_80290690: usize = 0x8029_0690;

/// Shape sampler `0x8028F860` (selector `4`), translated as [`fn_8028f860`].
/// Ghidra: `8028f860_FUN_8028f860.c`.
const FN_8028F860: usize = 0x8028_F860;

/// Shape sampler `0x8028FEA0` (selector `5`), translated as [`fn_8028fea0`].
/// Ghidra: `8028fea0_FUN_8028fea0.c`.
const FN_8028FEA0: usize = 0x8028_FEA0;

/// Three-float normaliser, shared by the cylinder sampler's flag-`2` block.
/// Ghidra: `801c1470_FUN_801c1470.c`.
const FN_801C1470: usize = 0x801C_1470;

/// Calls `(r3, r4, r5, r6, r7, r8, r9, r10) -> f1`.
///
/// # Safety
/// `addr` must be a PowerPC function with that EABI shape.
#[inline]
unsafe fn call_f32ret_8(
    addr: usize,
    a: u32,
    b: u32,
    c: u32,
    d: u32,
    e: u32,
    f: u32,
    g: u32,
    h: u32,
) -> f32 {
    let func = crate::platform::guest_fn!(addr, fn(u32, u32, u32, u32, u32, u32, u32, u32) -> f32);
    func(a, b, c, d, e, f, g, h)
}

/// Picks one of six shape samplers, runs it, and on a hit writes the matching
/// world-space vectors.
///
/// The state object's dispatch byte at `+0x29` selects one of six classifiers and
/// one of six samplers:
///
/// | id | classifier | sampler |
/// |---:|---|---|
/// | 0 | `0x8028E7E0` | `0x8028E890` |
/// | 1 | `0x8028E6F0` | `0x8028ED30` |
/// | 2 | `0x8028E5E0` | `0x8028F2D0` |
/// | 3 | `0x8028E430` | `0x80290690` |
/// | 4 | `0x8028E310` | `0x8028F860` |
/// | 5 | `0x8028E510` | `0x8028FEA0` |
///
/// Each classifier receives `point_to` and the selector byte `state+0x2A`; each
/// sampler receives `(matrix_world, state, point_to, point_from, &delta,
/// direction, channel_arg, source)` and returns a signed fraction. When that
/// fraction is `<= 1.5` (the raw `0x8042EC50` compare) the entry writes output
/// vectors and returns `1`, otherwise it returns `0` without touching memory.
///
/// The two output paths differ only in how the delta is used:
///
/// * flag bit 2 and bit 8 both clear: `transformed = matrix_local * direction`
///   and `out_vector = matrix_world * point_to`.
/// * otherwise: `transformed` is scaled per axis by `state+0x30..+0x38`, and
///   `out_vector = source + matrix_local * ((0 - fraction) * delta)` scaled by
///   the same three factors.
///
/// Flag bit `0x40` copies `source` over `out_vector` and sets the byte at
/// `flag_out`; bits `0x10`/`0x20` additionally dispatch to `0x80296DD0` /
/// `0x80296F50` when `param_4` is non-zero.
///
/// Every `psq_l`/`psq_st` here uses `I = 0` (GQR0). The init path at `0x801AB150`
/// leaves all eight GQRs at `0` (float) and the only other writer is the
/// save-area restore at `0x802EA6FC`, so the export's quantisation ladders
/// collapse to plain `f32` moves.
///
/// # Original
/// - Ghidra: `FUN_80290cf0` at `0x80290CF0` (1032 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80290cf0_FUN_80290cf0.c`
/// - Raw check: `work/dol/main.elf` at `0x80290CF0..0x802910F8`
///
/// # Arguments
/// - `matrix_world`: `r3`; transform applied to `point_to` (and sampler slot 1).
/// - `matrix_local`: `r4`; transform applied to `direction` / the delta.
/// - `state`: `r5`; dispatch byte `+0x29`, selector byte `+0x2A`, flag word
///   `+0x2C`, axis scales `+0x30..+0x38`, tail record `+0x3C`.
/// - `param_4`: `r6`; gates the two tail dispatches.
/// - `owner`: `r7`; `+0xC8` roots the chain `+0xC8 -> +0x20 -> +0xBC -> +0x20 ->
///   +0x10` passed to the tails, and `+0xE2` is their u16 argument.
/// - `point_from`: `r8`; first point of the delta pair.
/// - `point_to`: `r9`; second point, also classified and transformed.
/// - `direction`: `r10`; transformed into `transformed`.
/// - `flag_out`: stack `+8`; one byte written when flag `0x40` is set.
/// - `channel_arg`: stack `+12`; sampler argument 7.
/// - `source`: stack `+16`; vector copied/scaled into `out_vector`.
/// - `out_vector`: stack `+20`; three writable floats.
/// - `transformed`: stack `+24`; three writable floats.
///
/// # Returns
/// `1` when a sampler reported a hit (`<= 1.5`), else `0`.
///
/// # Side effects
/// One classifier call, one sampler call, up to two matrix transforms, up to
/// three `f32` stores into each of `out_vector`/`transformed`, one optional byte
/// store at `flag_out`, and the optional tail dispatches.
///
/// # Safety
/// `matrix_world`, `matrix_local` must be 12-float readable matrices; `state`,
/// `owner` and the twelve-byte vectors must be readable; `out_vector` and
/// `transformed` must be writable; the six samplers must exist.
///
/// # Confidence
/// medium - the dispatch table, the `<= 1.5` guard, every offset and all three
/// tails were read from `main.elf`. The sampler call shape is reproduced
/// register for register; after wave 110 selectors `0`, `1` and `2`
/// ([`fn_8028e890`], [`fn_8028ed30`], [`fn_8028f2d0`]) are translated, wave 111
/// adds selector `3` ([`fn_80290690`]) and wave 121 adds selectors `4` and `5`
/// ([`fn_8028f860`], [`fn_8028fea0`]), so the address call is now only a
/// shortcut.
pub unsafe fn fn_80290cf0(
    matrix_world: usize,
    matrix_local: usize,
    state: usize,
    param_4: usize,
    owner: usize,
    point_from: usize,
    point_to: usize,
    direction: usize,
    flag_out: usize,
    channel_arg: u32,
    source: usize,
    out_vector: usize,
    transformed: usize,
) -> u32 {
    // observed: sdata2 0x8042EC50 = 1.5f (hit limit; the export's
    // `unaff_r2 - 0x4430`), 0x8042EBA4 = 0.0f.
    let hit_limit = read_f32(0x8042_EC50);
    let zero = read_f32(0x8042_EBA4);

    // observed: the selector byte is loaded once before the first switch and is
    // still in `r4` for every case, so all six classifiers see it.
    let mode = platform::read_u8(state + 0x29);
    let selector = platform::read_u8(state + 0x2a) as u32;
    match mode {
        0 => {
            fn_8028e7e0(point_to, selector as i32);
        }
        1 => {
            fn_8028e6f0(point_to, selector as i32);
        }
        2 => {
            fn_8028e5e0(point_to, selector as i32);
        }
        3 => {
            fn_8028e430(point_to);
        }
        4 => {
            fn_8028e310(point_to, selector);
        }
        5 => {
            fn_8028e510(point_to);
        }
        _ => {}
    }

    // observed: the delta pair is `point_to - point_from`, laid out as two
    // floats plus one scalar in the caller's frame.
    let mut delta = crate::platform::GuestLocal::new( [zero; 3]);
    delta[0] = read_f32(point_to) - read_f32(point_from);
    delta[1] = read_f32(point_to + 4) - read_f32(point_from + 4);
    delta[2] = read_f32(point_to + 8) - read_f32(point_from + 8);

    let sampler = match platform::read_u8(state + 0x29) {
        0 => FN_8028E890,
        1 => FN_8028ED30,
        2 => FN_8028F2D0,
        3 => FN_80290690,
        4 => FN_8028F860,
        5 => FN_8028FEA0,
        _ => 0,
    };
    let result = if sampler == 0 {
        zero
    } else {
        call_f32ret_8(
            sampler,
            matrix_world as u32,
            state as u32,
            point_to as u32,
            point_from as u32,
            delta.as_ptr() as u32,
            direction as u32,
            channel_arg,
            source as u32,
        )
    };

    // observed: `fcmpu` + `bf` on the GT bit, so an unordered result also takes
    // the early exit.
    if result > hit_limit {
        return 0;
    }

    let flags = platform::read_u16(state + 0x2c);
    if flags & 0x02 == 0 && flags & 0x08 == 0 {
        call3(
            FN_801C1160,
            matrix_local as u32,
            direction as u32,
            transformed as u32,
        );
        call3(
            FN_801C1160,
            matrix_world as u32,
            point_to as u32,
            out_vector as u32,
        );
    } else {
        call3(
            FN_801C1160,
            matrix_local as u32,
            direction as u32,
            transformed as u32,
        );
        write_f32(transformed, read_f32(transformed) * read_f32(state + 0x30));
        write_f32(
            transformed + 4,
            read_f32(transformed + 4) * read_f32(state + 0x34),
        );
        write_f32(
            transformed + 8,
            read_f32(transformed + 8) * read_f32(state + 0x38),
        );

        // observed: `0 - fraction` then `ps_muls0` over the three delta lanes.
        let shrink = zero - result;
        let mut scaled = crate::platform::GuestLocal::new( [delta[0] * shrink, delta[1] * shrink, delta[2] * shrink]);
        call3(
            FN_801C1160,
            matrix_local as u32,
            scaled.as_ptr() as u32,
            scaled.as_mut_ptr() as u32,
        );
        scaled[0] *= read_f32(state + 0x30);
        scaled[1] *= read_f32(state + 0x34);
        scaled[2] *= read_f32(state + 0x38);
        write_f32(out_vector, read_f32(source) + scaled[0]);
        write_f32(out_vector + 4, read_f32(source + 4) + scaled[1]);
        write_f32(out_vector + 8, read_f32(source + 8) + scaled[2]);
    }

    if platform::read_u16(state + 0x2c) & 0x40 != 0 {
        platform::write_u8(flag_out, 1);
        write_f32(out_vector, read_f32(source));
        write_f32(out_vector + 4, read_f32(source + 4));
        write_f32(out_vector + 8, read_f32(source + 8));
    }

    // observed: the tail chain is `owner+0xC8`, `+0x20`, `+0xBC`, `+0x20`,
    // `+0x10`; `owner+0xE2` is a u16 argument. Both tails are gated by
    // `param_4 != 0` and their own flag bit.
    let tail_flags = platform::read_u16(state + 0x2c);
    if tail_flags & 0x30 != 0 && param_4 != 0 {
        let root = platform::read_u32(owner + 0xc8) as usize;
        let root = platform::read_u32(root + 0x20) as usize;
        let root = platform::read_u32(root + 0xbc) as usize;
        let root = platform::read_u32(root + 0x20) as usize;
        let tail_object = platform::read_u16(owner + 0xe2) as u32;

        if tail_flags & 0x10 != 0 {
            call7(
                FN_80296DD0,
                (root + 0x10) as u32,
                (state + 0x3c) as u32,
                owner as u32,
                param_4 as u32,
                tail_object,
                source as u32,
                0,
            );
        }
        // observed: the flag word is re-read between the two tails.
        if platform::read_u16(state + 0x2c) & 0x20 != 0 {
            call7(
                FN_80296F50,
                (root + 0x10) as u32,
                (state + 0x3c) as u32,
                owner as u32,
                param_4 as u32,
                tail_object,
                source as u32,
                0,
            );
        }
    }

    1
}

// ---------------------------------------------------------------------------
// Wave 110: the three plain-float shape samplers of the `0x8028xxxx` dispatch.
//
// `0x80290CF0` selects one of six samplers through the byte at `state+0x29`
// (see [`fn_80290cf0`]). Five of those six were still open after wave 109. Three
// of them - selectors 0, 1 and 2 - are the same body and only differ in the
// in-plane rejection they apply after the sample has been built, so the shared
// skeleton lives in [`sample_shape`].
//
// Every `psq_l`/`psq_st` in the three exports carries `I = 0`, i.e. GQR0, and
// the init path at `0x801AB150` leaves GQR0 at plain float (`type 0`, `scale
// 0`). Each Ghidra `bVar == 4/6` (char) and `bVar == 5/7` (short) ladder is
// therefore unreachable and the `else` arm is the whole translation. The
// `ldexpf` calls Ghidra prints are the same quantiser expression with a scale
// of one.
//
// All four `sdata2` constants are read from `main.elf`: `0x8042EC30` is
// `FLT_EPSILON`, `0x8042EC28` is `0.0`, `0x8042EC2C` is the `2.0` "no hit"
// sentinel and `0x8042EC20` is `-1.0`.

/// Which in-plane rejection a shape sampler applies to its sample.
#[derive(Clone, Copy, PartialEq, Eq)]
enum ShapeClamp {
    /// No rejection: the plain segment sampler `0x8028E890`.
    None,
    /// Reject outside the unit square (`0x8028ED30`).
    Square,
    /// Reject outside the unit disc (`0x8028F2D0`).
    Disc,
}

/// Shared skeleton of the three shape samplers `0x8028E890`, `0x8028ED30` and
/// `0x8028F2D0`.
///
/// The sampler intersects the segment `point_from -> point_to` with the plane of
/// one world axis, lerps the three components of the segment with that
/// parameter, optionally mirrors the in-plane direction and nudges the hit
/// point by one epsilon step, applies the caller's in-plane rejection and
/// finally transforms the sample by the 3x4 matrix.
///
/// # Arguments
/// - `clamp`: which in-plane rejection to apply (the only difference between
///   the three translated entries).
/// - `matrix`: `r3`; 3x4 matrix passed straight to `0x801C1160`.
/// - `state`: `r4`; axis selector `+0x2A`, flag word `+0x2C`.
/// - `point_to`: `r5`; three segment start floats (the C calls it `param_3`).
/// - `point_from`: `r6`; three segment end floats (`param_4`).
/// - `delta`: `r7`; three delta floats (`param_5`), also mirrored on flag `2`.
/// - `direction`: `r8`; three direction floats (`param_6`), mirrored on flag `2`.
/// - `sample`: `r9`; three writable floats for the hit point (`param_7`).
/// - `out`: `r10`; three writable floats for the transformed point (`param_8`).
///
/// # Returns
/// The segment parameter, or `2.0` when the segment misses.
///
/// # Side effects
/// Up to three `f32` stores into `sample`, one optional `f32` store each into
/// `delta`/`direction`, one call to `0x801C1160`, and three `f32` stores into
/// `out` inside that call.
///
/// # Safety
/// `state` must be readable; `point_to`, `point_from`, `delta` and `direction`
/// must hold three readable floats each; `sample` and `out` must be three
/// writable floats each; `matrix` must be a readable 3x4 matrix.
#[inline]
unsafe fn sample_shape(
    clamp: ShapeClamp,
    matrix: usize,
    state: usize,
    point_to: usize,
    point_from: usize,
    delta: usize,
    direction: usize,
    sample: usize,
    out: usize,
) -> f32 {
    // observed: sdata2 constants, dumped from `work/dol/main.elf`.
    let eps = read_f32(0x8042_EC30);
    let zero = read_f32(0x8042_EC28);
    let miss = read_f32(0x8042_EC2C);
    let minus_one = read_f32(0x8042_EC20);

    let selector = platform::read_u8(state + 0x2a) as usize;
    if selector > 2 {
        return miss;
    }

    // observed: every arm reads its guard component after `selector`; the
    // indices it uses are 1, 2 and 0 for selectors 0, 1 and 2.
    let axis = (selector + 1) % 3;

    let from_axis = read_f32(point_from + 4 * axis);
    let to_axis = read_f32(point_to + 4 * axis);

    // observed: `FLT_EPSILON <= |from| || FLT_EPSILON <= |to|`, then the
    // six-way sign test. `step` is the direction of the epsilon nudge: `+1`
    // when the segment runs from the positive side to the negative one, `-1`
    // in the other direction. Every other combination is a miss.
    let step = if eps <= from_axis.abs() || eps <= to_axis.abs() {
        if from_axis <= zero || eps <= to_axis {
            if zero <= from_axis || to_axis <= eps {
                return miss;
            }
            -1.0f32
        } else {
            1.0f32
        }
    } else {
        return miss;
    };

    // observed: `t = -from[axis] / delta[axis]`, then a three-lane lerp of the
    // whole segment. The export reads all six inputs (two `psq_l` pairs and one
    // scalar each) before it stores anything.
    let t = -from_axis / read_f32(delta + 4 * axis);
    let to0 = read_f32(point_to);
    let to1 = read_f32(point_to + 4);
    let to2 = read_f32(point_to + 8);
    let from0 = read_f32(point_from);
    let from1 = read_f32(point_from + 4);
    let from2 = read_f32(point_from + 8);
    write_f32(sample, (to0 - from0) * t + from0);
    write_f32(sample + 4, (to1 - from1) * t + from1);
    write_f32(sample + 8, (to2 - from2) * t + from2);

    // observed: the in-plane partners of the guard axis.
    let (plane_a, plane_b) = match axis {
        0 => (1usize, 2usize),
        1 => (0, 2),
        _ => (0, 1),
    };
    match clamp {
        ShapeClamp::None => {}
        ShapeClamp::Square => {
            // observed: `1 + FLT_EPSILON <= |a| || 1 + FLT_EPSILON <= |b|`.
            let limit = read_f32(0x8042_EC34);
            if limit <= read_f32(sample + 4 * plane_a).abs()
                || limit <= read_f32(sample + 4 * plane_b).abs()
            {
                return miss;
            }
        }
        ShapeClamp::Disc => {
            // observed: `1 + 2*FLT_EPSILON <= a*a + b*b`.
            let limit = read_f32(0x8042_EC38);
            let a = read_f32(sample + 4 * plane_a);
            let b = read_f32(sample + 4 * plane_b);
            if limit <= a * a + b * b {
                return miss;
            }
        }
    }

    // observed: flag `2` mirrors the two input vectors on the guard axis and
    // moves the hit point by one epsilon step in the `step` direction.
    if platform::read_u16(state + 0x2c) & 0x02 != 0 {
        write_f32(
            direction + 4 * axis,
            read_f32(direction + 4 * axis) * minus_one,
        );
        write_f32(delta + 4 * axis, read_f32(delta + 4 * axis) * minus_one);
        write_f32(
            sample + 4 * axis,
            read_f32(sample + 4 * axis) + step * eps,
        );
    }

    call3(
        FN_801C1160,
        matrix as u32,
        sample as u32,
        out as u32,
    );

    t
}

/// Segment sampler 0: intersects the `point_from -> point_to` segment with the
/// plane of the axis selected by `state+0x2A`, lerps the hit point and transforms
/// it by the 3x4 matrix. No in-plane rejection.
///
/// This is selector `0` of the dispatch in [`fn_80290cf0`] and the plainest
/// member of the family: the other two differ only in the [`sample_shape`]
/// clamp they pass.
