/// * `this` - the text record (`r3`).
/// * `source` - wide-character source (`r4`).
/// * `count` - requested append length (`r5`).
///
/// # Returns
/// The number of units copied (`r3`), zero-extended.
///
/// # Side effects
/// Up to 30 bytes copied, one length halfword store and one terminator store.
///
/// # Safety
/// `source` must be a zero-terminated `u16` string; `this + 0xD8` must point
/// at a buffer with room for `count + 15` units.
///
/// # Confidence
/// high - the guards, size arithmetic and `memcpy` call are literal; the
/// capacity derivation is documented above.
pub unsafe fn fn_802aeec0(this: usize, source: u32, count: u32) -> u32 {
    let length = call1(D279_FN_802E441C, source) as u32;
    let buffer = platform::read_u32(this + 0xd8) as usize;
    if buffer == 0 {
        return 0;
    }

    // observed 0x802AEF08: cntlzw of the zero left by 0x802E441C.
    let capacity = 15u32;
    if count > capacity {
        return 0;
    }

    let room = capacity - count;
    let used = if length > room { room } else { length };
    call3(
        FN_80004364,
        (buffer + count as usize * 2) as u32,
        source,
        used * 2,
    );

    let total = count + used;
    platform::write_u16(this + 0xfe, total as u16);
    let base = platform::read_u32(this + 0xd8) as usize;
    platform::write_u16(base + total as usize * 2, 0);
    used
}

